import * as T from './vendor/three.module.js';
export function surfaceTexture(kind,repeatX=1,repeatY=1){const c=document.createElement('canvas');c.width=c.height=256;const g=c.getContext('2d');let seed=kind==='earth'?51:kind==='path'?79:97;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
g.fillStyle=kind==='earth'?'#41483c':kind==='path'?'#766755':'#705139';g.fillRect(0,0,256,256);
for(let i=0;i<14000;i++){const v=random();g.fillStyle=kind==='wood'?`rgba(28,15,8,${v*.28})`:`rgba(${v>.5?'176,165,130':'20,31,25'},${.12+random()*.24})`;g.fillRect(random()*256,random()*256,kind==='wood'?8+random()*30:1+random()*4,1+random()*2)}
if(kind==='wood'){for(let y=0;y<256;y+=32){g.fillStyle='#281f18';g.fillRect(0,y,256,3);for(let x=8;x<256;x+=64){g.fillStyle='#282c2b';g.fillRect(x,y+7,3,3)}}for(let i=0;i<9;i++){g.strokeStyle='#47311f';g.beginPath();g.ellipse(random()*256,random()*256,8,2,0,0,Math.PI*2);g.stroke()}}
else{for(let i=0;i<(kind==='earth'?160:95);i++){const x=random()*256,y=random()*256;g.fillStyle=kind==='earth'?(i%2?'#586344':'#353e2e'):(i%2?'#958574':'#534d43');g.beginPath();g.ellipse(x,y,2+random()*5,1+random()*3,random()*3,0,Math.PI*2);g.fill();if(kind==='earth'){g.strokeStyle='#72704a';g.beginPath();g.moveTo(x,y);g.lineTo(x+4,y+2);g.stroke()}}if(kind==='path'){g.strokeStyle='#53493766';for(const x of [74,181]){g.beginPath();g.moveTo(x,0);for(let y=0;y<=256;y+=16)g.lineTo(x+Math.sin(y/256*Math.PI*2)*4,y);g.stroke()}}}
// Larger, readable surface details remain visible in the cold night lighting.
if(kind==='earth'){for(let i=0;i<65;i++){const x=random()*256,y=random()*256;g.fillStyle=i%3?'#344939':'#716342';g.beginPath();g.ellipse(x,y,3+random()*5,1.5,random()*Math.PI,0,Math.PI*2);g.fill();g.strokeStyle='#202e26';g.beginPath();g.moveTo(x-2,y);g.lineTo(x+3,y+1);g.stroke()}for(let i=0;i<18;i++){g.strokeStyle='#66704b55';g.lineWidth=1;g.beginPath();const x=random()*256,y=random()*256;g.moveTo(x,y);g.quadraticCurveTo(x+12,y-4,x+20,y+3);g.stroke()}}
if(kind==='path'){for(let i=0;i<110;i++){const x=random()*256,y=random()*256,r=1+random()*4;g.fillStyle=i%3?'#898679':'#4a4d47';g.beginPath();g.ellipse(x,y,r,r*.7,random()*Math.PI,0,Math.PI*2);g.fill();g.fillStyle='#bab39a66';g.fillRect(x-r*.5,y-r*.4,r,1)}g.lineWidth=1;g.strokeStyle='#292c2466';for(let i=0;i<18;i++){const x=random()*256,y=random()*256;g.beginPath();g.moveTo(x,y);g.lineTo(x+3,y+4);g.lineTo(x-1,y+8);g.stroke()}}
if(kind==='wood'){g.lineWidth=1;for(let i=0;i<28;i++){const y=random()*256;g.strokeStyle=i%2?'#a17b4b55':'#20190f88';g.beginPath();g.moveTo(0,y);for(let x=0;x<=256;x+=8)g.lineTo(x,y+Math.sin(x/256*Math.PI*4+i)*2);g.stroke()}for(let y=16;y<256;y+=32)for(let x=16;x<256;x+=64){g.fillStyle='#11191b';g.fillRect(x,y,3,3);g.fillStyle='#8d8b76';g.fillRect(x,y,1,1)}}
if(kind==='stone'){g.fillStyle='#687478';g.fillRect(0,0,256,256);for(let y=0;y<256;y+=32)for(let x=-32;x<256;x+=64){const offset=(y/32)%2*32;g.fillStyle='rgba(18,28,34,'+(.12+random()*.2)+')';g.fillRect(x+offset+2,y+2,61,29);g.strokeStyle='#283941';g.strokeRect(x+offset,y,64,32)}for(let i=0;i<1500;i++){g.fillStyle=random()<.5?'#70817c':'#435651';g.fillRect(random()*256,random()*256,2,1)}}const tex=new T.CanvasTexture(c);tex.wrapS=tex.wrapT=T.RepeatWrapping;tex.repeat.set(repeatX,repeatY);tex.magFilter=T.NearestFilter;tex.colorSpace=T.SRGBColorSpace;return tex}
